style.css:
@-moz-document domain("pikabu.ru") {
/* Pikabu ships a fully tokenised design system (~900 CSS custom properties).
     The cleanest, most stable retheme is to flip the light palette tokens to a
     dark equivalent at :root, then add a thin structural safety net for the few
     surfaces that use literal colours or inherit a transparent background from
     the body. Brand green and semantic colours (vote up/down, badges, awards)
     are preserved — only their tone is refined to sit well on the dark canvas. */

  :root {
    color-scheme: dark !important;

    /* ---- Local palette ---- */
    --pk-bg: #14181d;            /* base canvas */
    --pk-surface: #1c2128;       /* elevated cards (stories, comments) */
    --pk-surface-2: #1a1f26;     /* secondary surface (inputs, chips) */
    --pk-header: #0d1117;        /* header / footer */
    --pk-border: #2a313a;        /* subtle borders */
    --pk-border-soft: #232931;   /* very subtle dividers */
    --pk-text: #e6edf3;          /* primary text */
    --pk-text-soft: #c4cdd6;     /* body text */
    --pk-text-muted: #8b949e;    /* muted / hints / placeholder */
    --pk-green: #8fd35c;          /* refined Pikabu green (brand) */
    --pk-green-hover: #a4e072;
    --pk-green-deep: #6fae44;    /* green RINGS and outlines (never under white text) */
    --pk-green-shade: #598039;   /* green FILLS that carry a white label — 4.6:1 */

    /* ---- Flip the "bright"/"blackjack"/"black" greyscale ramps ----
       Pikabu's neutral ramps run light→dark; we re-map the light end of each to
       dark surfaces and the dark end to light text, so every component built on
       these tokens themes itself. */
    --color-bright-900: var(--pk-surface);
    --color-bright-800: var(--pk-surface);
    --color-linear-bright-900: var(--pk-surface);
    --color--header__bg: var(--pk-header);
    --footer-bg: var(--pk-header);

    --color-blackjack-100: var(--pk-surface);   /* was #fcfdff */
    --color-blackjack-99: var(--pk-bg);          /* was #f7f8fc */
    --color-blackjack-97: var(--pk-surface-2);   /* was #f2f3f7 */
    --color-blackjack-90: var(--pk-border);      /* was #dfe1e5 */
    --color-blackjack-75: #6b7480;
    --color-blackjack-70: var(--pk-text-muted);  /* was #aaacb2 */
    --color-blackjack-60: var(--pk-text-muted);  /* was #909299 */
    --color-blackjack-50primary: #9aa3ad;        /* was #757880 */
    --color-blackjack-30: var(--pk-text-soft);   /* was #45474d */
    --color-blackjack-18: var(--pk-text);        /* was #292a2e */
    --color-blackjack-15: var(--pk-text);        /* was #222326 */
    --color-blackjack-10: var(--pk-text);        /* was #1f2021 */

    --color-black-100: var(--pk-surface);        /* was #f9f9fb */
    --color-black-200: var(--pk-surface);        /* was #f9f9fb */
    --color-black-300: var(--pk-bg);             /* was #f7f8fc */
    --color-black-400: var(--pk-border);         /* was #e9e9e9 */
    /* NOT a surface token: black-420 is only ever used as `color`, for the label on
       the video-player scrim. Pikabu keeps it #e9e9e9 in its own dark theme too. */
    --color-black-420: #e9e9e9;
    --color-black-430: var(--pk-border);         /* was #ebedf2 */
    --color-black-440: var(--pk-border);
    --color-black-500: #4a525c;                  /* was #d8dadd */
    --color-black-600: #7d8893;                  /* was #b0b3bb */
    --color-black-700: #aab3bd;                  /* was #70737b */
    --color-black-800: var(--pk-text-soft);      /* was #444850 */
    --color-black-900: var(--pk-text);           /* was #212121 */
    --color-black-920: var(--pk-text);
    --color-black-940: var(--pk-text);           /* body text was #1b1e24 */

    /* ---- Background / surface design tokens ---- */
    --s-colorBg-clear: var(--pk-surface);
    --s-colorBg-tonned: var(--pk-bg);
    --s-colorBg-stroke: var(--pk-border);
    --s-colorBg-special: #2a2718;
    --s-colorBg-popup: rgba(0, 0, 0, 0.64);

    --s-text-heading-primary: var(--pk-text);
    --s-text-paragraph-primary: var(--pk-text);
    --s-text-paragraph-secondary: var(--pk-text-soft);
    --s-text-subheading-primary: var(--pk-text);
    --s-text-label-primary: var(--pk-text-soft);
    --s-text-label-secondary: var(--pk-text-muted);
    --s-text-label-tertiary: var(--pk-text-muted);
    --user-name-text: var(--pk-text);
    /* Neutral secondary-link token. Pikabu's light default is a near-black #37393d;
       it lifts it to #ced1d9 in its own dark theme. We never remapped it, so every
       element that reads it stayed dark-on-dark — most visibly the topic NAME heading
       (.page-topics__topic-name) on /themes, which rendered ~1.3:1 while its own note
       below sat bright. Also feeds a right-sidebar username and footer links. */
    --c-link-secondary-default: var(--pk-text-soft);

    /* ---- Inputs / textareas / comboboxes / selects ---- */
    --c-input-bgDefault: var(--pk-surface-2);
    --c-input-bgDisabled: var(--pk-bg);
    --c-input-strokeDefault: var(--pk-border);
    --c-input-textDefault: var(--pk-text-muted);
    --c-textarea-bgDefault: var(--pk-surface-2);
    --c-textarea-bgDisabled: var(--pk-bg);
    --c-textarea-strokeDefault: var(--pk-border);
    --c-textarea-textFilled: var(--pk-text);
    --c-combobox-bgDefault: var(--pk-surface-2);
    --c-combobox-bgDisabled: var(--pk-bg);
    --c-combobox-content-bg: var(--pk-bg);
    --c-combobox-strokeDefault: var(--pk-border);
    --c-combobox-content-stroke: var(--pk-border);
    --c-combobox-contentDefault: var(--pk-text-muted);
    --c-combobox-contentFilled: var(--pk-text);
    --c-combobox-contentDisabled: var(--pk-text-muted);
    /* Suggestion list (tag/author filters). Only rendered once the field is focused
       and typed into, so no load-time scan sees it: the item label kept #292a2e and
       the matched substring a pale #eaffd9 chip — invisible / glaring on the dark list. */
    --c-combobox-list-textPrimary: var(--pk-text-soft);
    --c-combobox-list-textSecondary: var(--pk-text-muted);
    --c-combobox-list-hover: var(--pk-surface);
    --c-combobox-list-click: var(--pk-border);
    --c-combobox-searchBg: #3a4d2a;
    --c-select-main-bgDefault: var(--pk-surface-2);
    --c-select-main-bgDisabled: var(--pk-bg);
    --c-select-main-strokeDefault: var(--pk-border);
    --c-select-list-bg: var(--pk-surface);
    --c-select-list-item-text: var(--pk-text);
    /* The Select/Dropdown panel paints itself from --c-select-list-item-default (NOT
       -bg). It is portaled into <body> only while open, so a load-time scan never sees
       it: the panel stayed #fcfdff white under our light item text. */
    --c-select-list-item-default: var(--pk-surface);
    --c-select-list-item-hover: var(--pk-surface-2);
    --c-select-list-item-click: var(--pk-border);
    --c-selectBtn-bgDefault: var(--pk-surface-2);
    --c-selectBtn-bgHover: var(--pk-surface);
    --c-selectBtn-stroke: var(--pk-border);

    /* Pressed state of the SelectBtn family (topic chips at the top of the feed) and
       the label colour they share. Both keep Pikabu's light defaults (#f2f3f7 pill /
       #292a2e near-black label), so pressing a chip flashes a white slab. */
    --c-selectBtn-bgClick: var(--pk-border);
    --c-selectBtn-text: var(--pk-text);

    /* Header nav hover/press (Горячее / Лучшее / Свежее / …). Pikabu paints the pill
       from these two tokens, which stay #f2f3f7 / #ebedf2 — so hovering any main nav
       item drops a solid near-white block behind our light label. */
    --c-navigation-horizontal-hover: var(--pk-surface);
    --c-navigation-horizontal-click: var(--pk-border);

    /* Label/icon on a filled PRIMARY button (.pkb-normal-btn — login modal actions,
       "Больше видео", the games-carousel "Играть", the footer app CTA). Pikabu keeps it
       #fcfdff, which lands ~1.9:1 on this theme's lightened brand green. Flip it dark,
       exactly as --color-bright-900 above. */
    --c-btn-primary-textIcon: var(--pk-bg);

    /* Collapse / power-rating toggles (the small +/− square in the feed rail and the
       comment collapse button) paint their hover+press fill from these; both stay light. */
    --collapse-hover: var(--pk-border);
    --collapse-click: #39414b;

    /* Reaction pill press state and the reaction-picker popover states — all light
       greys natively, so pressing a reaction flashes a bright slab. The "donated"
       pill's own fill matches the .emotion-btn_donated rule further down. */
    --reaction-click: var(--pk-border);
    --reaction-popover-hover: var(--pk-border);
    --reaction-popover-click: #39414b;
    --reaction-popover-active: #39414b;
    --reaction-donat-default: #2a2318;
    /* The reaction PICKER (.emotions-modal, opened from the "+" smiley beside a post's
       reaction row) marks recently-added reactions with .emotions-modal__btn_new, whose
       whole tile is painted from this pale-green family — eight #eaffd9 tiles glaring
       through the dark picker. The picker is portaled in on click, so no load-time scan
       sees it. Pikabu's own dark theme gives the family a dark-green equivalent that
       keeps the "new" signal; use it. The donate tile's hover/press are the same story. */
    --reaction-popover-newDefault: #1d2615;
    --reaction-popover-newHover: #26331c;
    --reaction-popover-newClick: #47662e;
    --reaction-popover-newStroke: #3a4d2a;
    --reaction-donat-hover: #352c1e;
    --reaction-donat-click: #2e2b1f;

    /* "Продвинуть" (promote) button on your own post: a pale-green #f4ffeb pill with a
       pale-green ring. Same dark-green family as above; the label goes to the theme's
       brand green, which carries it at 5.1:1 (Pikabu's own #78b247 lands at 3.7:1). */
    --story-btn-promote-default: #3a4d2a;
    --story-btn-promote-hover: #47662e;
    --story-btn-promote-click: #598039;
    --story-btn-promote-stroke: #598039;
    --story-btn-promote-content: var(--pk-green);

    /* Truncation fade for LONG COMMENTS (.comment__show-all::before) and a community's
       collapsed description (.community-info-block__read-more::before). All three fades
       on the site (post body included) read these two tokens; only the post-body one had
       been pinned, so the other two still dissolved into a near-white band. */
    --story-readMore-gradientA: var(--pk-surface);
    --story-readMore-gradientB: rgba(28, 33, 40, 0);

    /* ---- Pale semantic tints ----
       Pikabu's "200"/"100" ramp ends are near-white washes used as SURFACES: green for
       highlights and hover rows, red for danger sections, amber for warnings/notices,
       blue for company-blog badges, and the two debate-position captions. None of them
       were remapped, so each shipped as a glaring light island on the dark canvas.
       Dark-tune every one while keeping its hue, so the signal survives. */
    --color-primary-100: #2a3a20;
    --color-primary-200: #2f4025;
    --color-danger-200: #2e1c1a;
    --color-warning-200: #2e2716;
    --color-blue-200: #16283a;
    --color-debate-light-first: #33201e;
    --color-debate-light-second: #1e2740;
    /* the caption labels that sit ON those two debate tints are Pikabu's saturated
       mid-tones, which fall under 3:1 on them — lift both */
    --color-debate-first: #ef6a5d;
    --color-debate-second: #8b96e8;

    /* Gamification button hover/press. Its default fill is pinned neutral further down,
       so keep these two on the same neutral ramp instead of Pikabu's pale orange. */
    --gamification-btn-hover: var(--pk-surface);
    --gamification-btn-click: var(--pk-border);

    /* ---- Tags / chips / quotes / tooltips / menus ---- */
    --c-tag-bgDefault: var(--pk-surface-2);
    --c-tag-bgHover: var(--pk-surface);
    --c-tag-bgContrastDefault: var(--pk-surface-2);
    --c-tag-bgContrastHover: var(--pk-surface);
    --c-tag-stroke: var(--pk-border);
    --c-tag-strokeContrast: var(--pk-border);
    --c-quote-bg: var(--pk-surface-2);
    --c-tooltip-bg: var(--pk-surface);
    --c-tooltip-text: var(--pk-text);
    --c-menu-item-text: var(--pk-text);
    --c-menu-item-hover: var(--pk-surface-2);
    --c-menu-item-click: var(--pk-border);
    --c-counter-bgTertiary: var(--pk-surface-2);
    /* filled counters keep a light brand/alert fill — flip their label dark to read */
    --c-counter-text: var(--pk-bg);

    /* ---- Secondary buttons (neutral greys) ---- */
    --c-btn-secondary-bgDefault: var(--pk-surface-2);
    --c-btn-secondary-bgHover: var(--pk-border);
    --c-btn-secondary-bgClick: var(--pk-border);
    --c-btn-secondary-textIcon: var(--pk-text-soft);
    --c-btnIcon-tertiary-bgDefault: var(--pk-surface-2);
    --c-btnIcon-tertiary-bgHover: var(--pk-surface);
    --c-btnIcon-tertiary-stroke: var(--pk-border);
    --c-btnSocialIcon-bgDefault: var(--pk-surface-2);
    --c-btnSocialIcon-bgHover: var(--pk-surface);
    --c-btnSocialIcon-bgClick: var(--pk-border);
    --c-social-bgWhite: var(--pk-surface);

    /* ---- Pagination ---- */
    --c-pagination-defaultBg: var(--pk-surface-2);
    --c-pagination-hoverBg: var(--pk-surface);
    --c-pagination-clickBg: var(--pk-border);
    --c-pagination-content: var(--pk-text-soft);
    /* The CURRENT page pill keeps --c-pagination-activeContent: #fcfdff, a white label,
       on a brand-green fill. Only the four inactive-state tokens above had been
       remapped, so the active pill still landed ~2:1. Use the deeper green Pikabu
       itself picks in its own dark theme, which carries the white label at 4.6:1. */
    --c-pagination-activeDefaultBg: var(--pk-green-shade);
    --c-pagination-activeHoverBg: #67993d;
    --c-pagination-activeClickBg: #6fa642;

    /* Switch toggles (search-filter sidebar: "[мое]", "Скрыть просмотренные"). The
       control draws its whole visual through pseudo-elements — ::before is the track,
       ::after the knob — so no element-bg scan sees it, and at 40x24 it also sits under
       the scanner's chip threshold. Both stayed on Pikabu's light defaults (#ced1d9
       track / #fcfdff knob), rendering as two bright pills on the dark sidebar. The
       whole component is token-driven, so remapping here needs no hashed class name.
       The ON state keeps the brand green; the knob goes dark so it reads on both. */
    --c-switch-mainDefault: #5e6066;
    --c-switch-mainHover: #6b7480;
    --c-switch-mainClick: #7d8893;
    --c-switch-toggle: var(--pk-bg);
    --c-switch-activeDefault: var(--pk-green);
    --c-switch-activeHover: var(--pk-green-hover);
    --c-switch-activeClick: var(--pk-green-deep);

    /* Date-range picker ("Выбрать дату" in the search filters). Every glyph in the
       sheet — both month titles and all ~70 day numbers — reads --c-calendar-content,
       a near-black #292a2e, so the whole popup rendered dark-on-dark; only the selected
       range was legible. The panel is portaled in on click, so no load-time scan sees
       it. --c-calendar-choose is the pale-green #eaffd9 band painted between the two
       ends of a range, and the two hover overlays are dark-on-dark films. */
    --c-calendar-content: var(--pk-text-soft);
    --c-calendar-choose: #1d2615;
    --c-calendar-bgHover: rgba(255, 255, 255, 0.08);
    --c-calendar-bgClick: rgba(255, 255, 255, 0.16);
    --c-calendar-activeBgDefault: var(--pk-green-shade);
    --c-calendar-activeBgHover: #67993d;
    --c-calendar-activeBgClick: #6fa642;

    /* Range slider (search "Рейтинг"). The track is one gradient: brand green up to the
       handle, --c-slider-lineBg beyond it. That empty half stayed #ebedf2, so narrowing
       the range exposed a near-white bar. At the default full-width setting the whole
       track is green, which is why it never showed up in a screenshot. */
    --c-slider-lineBg: var(--pk-border);
    --c-slider-active: var(--pk-green);
    --c-slider-stokeHover: #26331c;
    --c-slider-stokeClick: #3a4d2a;

    /* Custom scrollbars (the ui-kit paints ::-webkit-scrollbar-thumb from these). The
       thumb stayed #dcdee5 — a 20px near-white bar down the side of every scrollable
       panel, e.g. the tag-suggestion list. Not a native scrollbar, so `color-scheme:
       dark` does not reach it. */
    --c-scrollbar-default: #45474d;
    --c-scrollbar-hover: #5e6066;
    --c-scrollbar-click: #757880;

    /* Checkbox / radio. Both draw an UNCHECKED box as a solid #fcfdff fill with a
       #ced1d9 ring — a white square/disc on the dark canvas. The checked fill carries a
       white tick/dot, so it needs the deeper green for the mark to read. */
    --c-checkbox-mainBgDefault: #5e6066;
    --c-checkbox-mainBgHover: #757880;
    --c-checkbox-mainBgClick: #909299;
    --c-checkbox-mainStroke: #37393d;
    --c-checkbox-activeDefault: var(--pk-green-shade);
    --c-checkbox-activeHover: #67993d;
    --c-checkbox-activeClick: #6fa642;
    --c-radio-mainBgDefault: #5e6066;
    --c-radio-mainBgHover: #757880;
    --c-radio-mainBgClick: #909299;
    --c-radio-mainStroke: #37393d;
    --c-radio-activeDefault: var(--pk-green-shade);
    --c-radio-activeHover: #67993d;
    --c-radio-activeClick: #6fa642;

    /* Inactive carousel bullets (#ebedf2 = a row of white dots under a carousel). The
       ACTIVE bullet is left alone — it is the "you are here" marker. */
    --c-carouselBullets-medium-normal: #45474d;
    --c-carouselBullets-small-normal: #757880;

    /* Tab component. Its label tokens are Pikabu's near-blacks, and the "rounded"
       variant fills itself #fcfdff under a white --c-tab-roundedText label. */
    --c-tab-default: var(--pk-text-soft);
    --c-tab-hover: var(--pk-text);
    --c-tab-click: #ffffff;
    --c-tab-active: var(--pk-green);
    --c-tab-roundedBg: var(--pk-surface);

    /* VERTICAL navigation (profile side tabs). Only the `-horizontal-` half of this
       family had been remapped, so the vertical one kept a near-black label and a
       near-white hover/current fill. */
    --c-navigation-text: var(--pk-text-soft);
    --c-navigation-horizontal-textMainDefault: var(--pk-text-soft);
    --c-navigation-hover: var(--pk-surface);
    --c-navigation-active: var(--pk-surface);
    --c-navigation-click: var(--pk-border);

    /* Ghost ("text") button hover/press fills: pale-green and pale-pink washes that
       flash a light slab under the cursor. Only the label colours had been handled. */
    --c-btn-primaryText-bgHover: #26331c;
    --c-btn-primaryText-bgClick: #1d2615;
    --c-btn-negativeText-bgHover: #2e1c1a;
    --c-btn-negativeText-bgClick: #3d211d;

    /* The DANGER button (.pkb-normal-btn_negative-outline — destructive actions such as
       "Удалить") carries its whole identity in one token: it fills transparent and takes
       both its ring AND its label from --c-btn-negativeOutline-textStroke*. Pikabu's
       #cc4235 measures 3.4:1 on the elevated surface, under the WCAG floor; lift the
       family to the theme's danger red. (The ring also needs a selector rule further
       down — the blanket border reset outranks a :root remap.) */
    --c-btn-negativeOutline-textStrokeDefault: #ef6a5d;
    --c-btn-negativeOutline-textStrokeHover: #f4837a;
    --c-btn-negativeOutline-textStrokeClick: #d9483b;

    /* Remaining light control fills: tag press state, tertiary icon-button press,
       split-button neutral half, and the disabled small icon button. */
    --c-tag-bgClick: var(--pk-border);
    --c-tag-bgContrastClick: var(--pk-border);
    --c-tag-textContrast: var(--pk-text-soft);
    --c-btnIcon-tertiary-bgClick: var(--pk-border);
    --c-btnSplit-secondary-bgDefault: #5e6066;
    --c-btnIconSmall-disabled: #5e6066;

    /* Text tokens still on Pikabu's near-blacks. --c-link-secondary-default was lifted
       previously but its hover/click siblings were not, so hovering a secondary link
       (topic names on /themes, footer links) drove it BACK to near-black. */
    --c-link-secondary-hover: var(--pk-text);
    --c-link-secondary-click: var(--pk-text);
    --c-input-textFilled: var(--pk-text);
    --c-select-main-textSelected: var(--pk-text);
    --c-quote-text: var(--pk-text-soft);
    /* disabled tones: #ced1d9 reads brighter than the ENABLED text on dark, i.e. the
       control looks more active when it is disabled — invert that relationship */
    --c-input-textDisabled: #5e6066;
    --c-input-iconDisabled: #5e6066;
    --c-select-main-textDisabled: #5e6066;
    --c-select-main-iconDisabled: #5e6066;
    --c-textarea-textDisabled: #5e6066;

    /* ---- Alerts / captcha / collapse ---- */
    --c-alert-baseBg: var(--pk-surface-2);
    --c-alert-baseStroke: var(--pk-border);
    /* The three SEMANTIC alert variants were never remapped — only `base` was — so an
       accent / error / warning alert shipped as a near-white island. Dark-tune each
       while keeping its hue so the severity still reads. */
    --c-alert-accentBg: #1d2615;
    --c-alert-accentStroke: #3a4d2a;
    --c-alert-errorBg: #2e1c1a;
    --c-alert-errorStroke: #66120a;
    --c-alert-warningBg: #2e2716;
    --c-alert-warningStroke: #4f4522;
    --c-captcha-block-bg: var(--pk-surface-2);
    --c-captcha-block-stroke: var(--pk-border);
    /* the captcha's own answer buttons are a separate family from the block above */
    --c-captcha-test-btn-default: var(--pk-surface-2);
    --c-captcha-test-btn-hover: var(--pk-surface);
    --c-captcha-test-btn-click: var(--pk-border);
    --c-captcha-test-btn-stroke: var(--pk-border);
    --c-captcha-test-text: var(--pk-text-soft);
    --collapse-stroke: var(--pk-border);
    --c-bottomSheet-line: var(--pk-border);

    /* ---- Refine the brand green (keep hue family, lift for dark) ---- */
    --color-pikabu-80primary: var(--pk-green);
    --color-pikabu-75: var(--pk-green);
    --color-pikabu-60: var(--pk-green-deep);
    --color-primary-800: var(--pk-green);
    --color-primary-700: var(--pk-green);
    --color-primary-600: var(--pk-green);
    --color-primary-900: var(--pk-green-deep);
    --c-btn-primary-bgDefault: var(--pk-green);
    --c-btn-primary-bgHover: var(--pk-green-hover);
    --c-btn-primary-bgClick: var(--pk-green-deep);
    --c-btn-primaryText-textIcon: var(--pk-green);
    --c-navigation-horizontal-textActiveDefault: var(--pk-green);
    --c-counter-bgPrimary: var(--pk-green);
    --c-counter-textPrimary: var(--pk-green);
    --c-breadcrumbs-default: var(--pk-green);
    --s-colorTextSpecial-accent: var(--pk-green);

    /* ---- Rating: keep green up / red down, lift the tone for dark ---- */
    --rating-plus-active: var(--pk-green);
    --rating-plus-hover: var(--pk-green);
    --rating-plus-default: var(--pk-text-muted);
    --rating-plus-click: var(--pk-green-deep);
    --rating-minus-active: #ef6a5d;
    --rating-minus-hover: #ef6a5d;
    --rating-minus-default: var(--pk-text-muted);
    --rating-minus-click: #d9483b;
    --rating-progressMinus: #ef6a5d;
    --rating-icon: var(--pk-text-muted);
    --rating-text: var(--pk-text-muted);
    --rating-stroke: var(--pk-border);
    --rating-progressBg: var(--pk-border);
    --reaction-default: var(--pk-surface-2);
    --reaction-hover: var(--pk-surface);

    /* Fundraising (donate) progress bar. The EMPTY track reads --color-donate-bg,
       a pale-green #eaffd9 that we never remapped, so it shipped as a glaring light
       island across the dark story card while its centered "0%" label (lifted light)
       sat invisible on it. Only rendered on posts that carry a fundraising widget, so
       no home-page scan sees it. Dark-tune the track; the green fill (lineA/lineB) and
       the green amount labels are preserved. */
    --color-donate-bg: var(--pk-border);

    /* ---- Mid-tone tokens that lose contrast on dark ----
       The "pale token / near-black token" sweep only flags values whose channels are all
       >200 or all <95, so a MID grey or a saturated mid red slips through it while still
       failing WCAG once the surface goes dark. Each token below is Pikabu's light-theme
       value measured against --pk-surface, with its own dark-theme value as the fix. */

    /* #757880 = 3.66:1. Feeds the reaction-picker "+" smiley on every post and comment,
       the section/profile/community info icons, .pkb-icon-btn and the sidebar footer
       link column. Pikabu's dark theme lifts each of these itself. */
    --s-icon-primary: #b6b8bf;
    --c-btnIcon-primary-textIcon: #909299;
    --c-btnIcon-tertiary-textIcon: #b6b8bf;
    --sidebar-link-default: #909299;
    --sidebar-link-click: #aaacb2;
    --tabbar-contentDefault: #aaacb2;

    /* #e13d27 = 3.78:1 across 38 consumers — the NSFW tag, form/comment errors, the
       profile minus counter, ban icons and the community rules header. */
    --color-danger-900: #f75c48;

    /* Sole consumer is `.carousel__scroll svg { stroke: … }`, the games-carousel arrow;
       its #212121 stroke sat on a disc we darken to --pk-surface, i.e. no arrow at all. */
    --color-contrast-bg: var(--pk-text);

    /* ---- Subtle shadows: soften so they don't glow on dark ---- */
    --shadow-low: 0 1px 12px rgba(0, 0, 0, 0.4);
    --s-shadow-mainStroke: rgba(255, 255, 255, 0.06);
    --s-shadow-extraStroke: rgba(255, 255, 255, 0.06);
  }

  /* ===== Base canvas ===== */
  html { background-color: var(--pk-bg) !important; }
  body {
    background-color: var(--pk-bg) !important;
    color: var(--pk-text-soft) !important;
  }

  /* ===== Borders ===== (colour only — never adds a border, safe everywhere) */
  * { border-color: var(--pk-border) !important; }

  /* ===== Header ===== */
  .header,
  .header__inner,
  .header_with-ads,
  .app-header {
    background-color: var(--pk-header) !important;
    border-color: var(--pk-border) !important;
  }
  .header a,
  .header__nav a,
  .menu__link,
  .header-menu a { color: var(--pk-text-soft) !important; }
  .header a:hover,
  .menu__link:hover { color: var(--pk-text) !important; }
  /* The three round header buttons (search / add / notifications) are brand-green discs
     whose glyph paints from --c-btn-primary-textIcon, which we flip dark to read on
     green. Two of them are <a>, so the `.header a` label rule above repainted the glyph
     --pk-text-soft — a pale grey icon on bright green, ~1.1:1, while the search one (a
     <div>, unmatched) stayed correct. Restate the dark glyph for the anchors. */
  .header a.header-right-menu__add,
  .header a.header-right-menu__notification,
  .header a.header-right-menu__search {
    color: var(--pk-bg) !important;
  }
  .header-dropdown,
  .header-menu__dropdown,
  .menu-popup,
  .dropdown__content { background-color: var(--pk-surface) !important; }

  /* Mobile navigation drawer. The slide-in `.app__sidebar` (hamburger menu on the
     narrow/mobile layout) keeps Pikabu's light #f5f5f5 panel background, so every
     menu label — painted with our lightened text tokens — sits light-on-white and
     vanishes. Only visible once the burger is tapped, so no load-time scan sees it.
     Darken the panel to the base canvas; the labels and the dark game-promo tiles
     inside already read on it. */
  .app__sidebar { background-color: var(--pk-bg) !important; }

  /* The four Pikabu-project cards inside that drawer (Промокоды / Курсы / Работа / Игры).
     Each wordmark is an SVG painted with `currentColor`, and the card hardcodes
     `color: #222326` (Pikabu only lifts it under :root[data-theme-dark]) — so all four
     wordmarks render near-black on the dark drawer. The card fill reads --s-colorBg-tonned,
     which this theme maps to the base canvas, leaving the cards shapeless too: give them
     the elevated surface so the tiles read as tiles. */
  .sidebar-products-temp__card {
    background-color: var(--pk-surface) !important;
    color: var(--pk-text) !important;
  }

  /* ===== Main columns / feed wrappers (transparent over base) ===== */
  .app,
  .layout,
  .layout__content,
  .main,
  .wrapper,
  .page,
  .page__inner,
  .stories-feed,
  .stories-feed__container,
  .feed,
  .sidebar,
  .sidebar_right,
  .sidebar_left { background-color: transparent !important; }

  /* ===== Story / post cards ===== */
  .story,
  .story__main,
  .story-block,
  .page-story,
  .page-story__main { background-color: var(--pk-surface) !important; }
  .story__title,
  .story__title-link,
  .story-title,
  .page-story__title { color: var(--pk-text) !important; }
  .story__content-inner,
  .story__text,
  .story-block__content,
  .b-story-block__text { color: var(--pk-text-soft) !important; }
  .story__title-link:hover { color: var(--pk-green-hover) !important; }

  /* "Primary" colour text posts: the author picks a coloured background that is
     painted on .story__content-inner (with a decorative white-gloss overlay we
     keep). Our generic .story-block surface rule forced the nested text block to
     a dark surface, laying an opaque band across the middle of the coloured post.
     Keep the inner text block transparent so the author's colour shows through. */
  [class*="story_primary"] .story-block,
  [class*="story_primary"] .story-block_type_text { background-color: transparent !important; }

  /* Rating block on the story card */
  .story__rating-block { background-color: var(--pk-surface-2) !important; }
  .story__rating-count { color: var(--pk-text-soft) !important; }

  /* ===== Tags ===== */
  .tags__tag,
  .story__tags a,
  a.tag {
    background-color: var(--pk-surface-2) !important;
    color: var(--pk-text-soft) !important;
    border-color: var(--pk-border) !important;
  }
  .tags__tag:hover,
  .story__tags a:hover { background-color: var(--pk-surface) !important; color: var(--pk-text) !important; }

  /* Tag STATE variants carry meaning, and the blanket label colour above swallowed
     all three: `_nsfw` is the adult-content warning (danger red), `_added` /
     `_removed` mark a tag just added to / removed from your filters (green / red).
     Pikabu paints them from --color-danger-900 / --color-primary-900. Restore each,
     dark-tuned. The selectors must outrank our own `.story__tags a` rule (0,1,1),
     hence the doubled class / `.story__tags a…` forms. */
  .tags__tag.tags__tag_nsfw,
  .story__tags a.tags__tag_nsfw,
  a.tag_nsfw,
  .tags__tag.tags__tag_removed,
  .story__tags a.tags__tag_removed,
  a.tag_removed { color: #ef6a5d !important; }
  .tags__tag.tags__tag_added,
  .story__tags a.tags__tag_added,
  a.tag_added { color: var(--pk-green) !important; }

  /* ===== Comments tree ===== */
  .comments,
  .page-story__comments { background-color: var(--pk-surface) !important; }
  .comment,
  .comment__content,
  .comment__body { background-color: transparent !important; color: var(--pk-text-soft) !important; }
  .comment__user,
  .comment .user__nick { color: var(--pk-text) !important; }
  .comment-toolbar,
  .comments__sorting,
  .comment__children { background-color: transparent !important; }
  /* the thin nesting guide-lines between nested comments */
  .comment__branch,
  .comment__indent,
  .comment-thread__line { border-color: var(--pk-border) !important; background-color: var(--pk-border) !important; }

  /* The "expand/collapse thread" toggle (the small +/− square beside "раскрыть
     ветку N") is a green-filled pill: Pikabu paints its border AND fill from
     --color-primary-700, so it reads as a seamless green chip. Our universal
     `* { border-color }` reset flattened the ring to grey, wrapping every green
     toggle in a mismatched grey 1px outline. Restore the border to brand green. */
  .comment-toggle-children__icon { border-color: var(--pk-green) !important; }

  /* Pikabu marks the comment you wrote yourself with a filled username pill:
     `[data-own=true]` paints it from --color-black-700, a mid-grey (#70737b) that
     carried a white label. We lift that token to #aab3bd (it is a TEXT tone
     everywhere else), which turns the pill into a light grey slab under our light
     label — 1.3:1, effectively invisible. Give the pill its own dark fill so the
     "this is mine" marker survives. The OP pill ([data-own-story]) keeps its brand
     green, matching every other green fill on this theme. */
  .comment__user[data-own="true"] .user__nick {
    background-color: #4a525c !important;
    color: var(--pk-text) !important;
  }

  /* ===== Author / user blocks, avatars (do NOT tint the avatar image) ===== */
  .user__nick,
  .story__user-link,
  a.user { color: var(--pk-text) !important; }
  .avatar img,
  .user__avatar img,
  img.avatar { background-color: transparent !important; }

  /* ===== Search ===== */
  input[type="text"],
  input[type="search"],
  input[name="q"],
  .search-input,
  .input__field,
  textarea {
    background-color: var(--pk-surface-2) !important;
    color: var(--pk-text) !important;
    border-color: var(--pk-border) !important;
  }
  input::placeholder,
  textarea::placeholder { color: var(--pk-text-muted) !important; }
  .search-results,
  .search__results,
  .search-suggest { background-color: var(--pk-surface) !important; }

  /* ===== Login form — third-party provider buttons ===== */
  /* The provider buttons (VK / Yandex ID) keep their brand background, but their label
     is painted with --color-bright-900, which this theme remaps to a dark tone — on the
     black Yandex button that is near-invisible. Pin the label light. */
  .auth__provider-text,
  [class*="auth__provider"] .auth__provider-text { color: var(--pk-text) !important; }

  /* ===== Filter / sort / tab / segmented controls =====
     These interactive controls hardcode a near-black label colour (#292a2e /
     #37393d) for their UNSELECTED state, which is invisible on the dark canvas.
     Make every unselected label clearly readable (body-text tone), and keep the
     SELECTED/active state visually distinct (brand green or white-on-green) so
     the affordance is preserved. */

  /* Home feed sort tabs (Горячее / Лучшее / Свежее / Подписки) */
  .header-menu__item,
  .header-menu__item a,
  .header-menu a { color: var(--pk-text-soft) !important; }
  .header-menu__item:hover,
  .header-menu__item:hover a { color: var(--pk-text) !important; }
  /* current/selected feed sort stays brand green + bolder */
  .header-menu__item_current,
  .header-menu__item_current a,
  .header-menu__item_active,
  .header-menu__item_active a { color: var(--pk-green) !important; font-weight: 600 !important; }

  /* Search result tabs (Посты / Пользователи / Теги / Сообщества) */
  [class*="TabItem__tab"],
  [class*="TabItem__tab"] span { color: var(--pk-text-soft) !important; }
  [class*="TabItem__tab"]:hover { color: var(--pk-text) !important; }
  /* The pill background is painted by the tab's ::before pseudo, which hardcodes
     a near-white #fcfdff for unselected tabs (and brand green for the active one).
     Remap the unselected pill to a dark elevated surface so the light label reads,
     and refresh the active pill with the dark-tuned brand green. */
  [class*="TabItem__tab"]::before {
    background-color: var(--pk-surface-2) !important;
    border-color: var(--pk-border) !important;
  }
  [class*="TabItem__tab"]:hover::before { background-color: var(--pk-surface) !important; }
  /* The selected tab is marked by a data-tab-active ATTRIBUTE, not a class — the old
     [class*="TabItem__tab_active"] selectors never matched, so our neutral pill above
     painted the selected tab too and it read as unselected. Restore the green pill. */
  [class*="TabItem__tab"][data-tab-active],
  [class*="TabItem__tab"][data-tab-active] span { color: #ffffff !important; font-weight: 600 !important; }
  /* The fill must be the SHADE green, not the ring green: --pk-green-deep under this
     white label measures 2.7:1, which made the selected tab's own name the faintest
     text on the row — dimmer than the unselected tabs beside it and than the counter
     nested inside it. --pk-green-shade carries white at 4.6:1. */
  [class*="TabItem__tab"][data-tab-active]::before {
    background-color: var(--pk-green-shade) !important;
    border-color: var(--pk-green-shade) !important;
  }
  /* Counter pills nested in a tab must not inherit the tab's label colour: the filled
     "primary" counter sits on brand green, where a light label lands at ~1.1:1. The
     doubled attribute selector is needed to outrank the tab's own label rule. */
  [class*="Counter__host"][class*="_primary"],
  [class*="Counter__host"][class*="_primary"] span {
    color: var(--pk-bg) !important;
    -webkit-text-fill-color: var(--pk-bg) !important;
  }

  /* Search period / type segmented buttons (Сегодня / Неделя / Текстовые …) */
  [class*="SelectBtn__button"],
  [class*="SelectBtn__button"] span {
    background-color: var(--pk-surface-2) !important;
    color: var(--pk-text-soft) !important;
    border-color: var(--pk-border) !important;
  }
  [class*="SelectBtn__button"]:hover { background-color: var(--pk-surface) !important; color: var(--pk-text) !important; }
  /* active segmented button keeps the brand green pill with white label — on the SHADE
     green, which is the only one of our greens that carries white text above 4.5:1 */
  [class*="SelectBtn__button_active"],
  [class*="SelectBtn__button_active"] span {
    background-color: var(--pk-green-shade) !important;
    color: #ffffff !important;
    border-color: var(--pk-green-shade) !important;
  }

  /* Comment-sort + generic sorting controls (Лучшие / Новые / Старые …) */
  [class*="comments__sort"],
  [class*="comments__sort"] a,
  [class*="comments__sort"] span,
  [class*="sorting__item"],
  .comments__sorting a,
  .comments__sorting span { color: var(--pk-text-soft) !important; }
  [class*="sorting__item_active"],
  [class*="comments__sort"] .active,
  .comments__sorting .active { color: var(--pk-green) !important; font-weight: 600 !important; }

  /* A DISABLED comment-menu tab (e.g. "Автора" when the OP hasn't commented)
     hardcodes a near-black #2d3236 that was a light grey on the original light
     skin — invisible on the dark menu bar. Lift it to the muted tone so it still
     reads as disabled but is legible. */
  .menu__item_disabled,
  .menu__item_disabled span { color: var(--pk-text-muted) !important; }

  /* The inline "text" Select used as the result-sort trigger (e.g. "Сначала
     свежее") keeps a dark brand-green #598039 that drops below the WCAG floor on
     the dark canvas. Lift only this accent/text Select variant to the dark-tuned
     brand green; neutral dropdown Selects keep their token colours. */
  [class*="Select__host_text"] [class*="Select__label"] { color: var(--pk-green) !important; }

  /* The legacy sort selector on the Communities list ("Сортировать по
     актуальности ⌄") is a plain span.link[data-role="sort"] whose label + Font
     Awesome chevron keep Pikabu's darker brand green #67993d — it lands ~4.2:1 on
     the dark card, just under the WCAG floor, and reads dimmer than the modern
     Select above. Lift it (and its ::before chevron glyph) to the dark-tuned green. */
  span.link[data-role="sort"],
  span.link[data-role="sort"] span,
  span.link[data-role="sort"] i.fa { color: var(--pk-green) !important; }

  /* The "primary-text" ghost + "outline" green-accent button variants (e.g. the
     "Сбросить запрос" reset-query action on an empty search result, and the
     "Расширенный поиск" advanced-search action in the search flyout) hardcode the
     dark brand-green #598039 on their label, which lands ~2.9:1 on the dark card.
     Lift the label to the dark-tuned brand green so the action stays readable, and
     restore the outline variant's green border (our universal border rule flattens
     it to grey, erasing the button's affordance). */
  [class*="Btn__btn_primary-text"],
  [class*="Btn__btn_primary-text"] [class*="label"],
  [class*="Btn__btn_outline"],
  [class*="Btn__btn_outline"] [class*="label"] {
    color: var(--pk-green) !important;
    -webkit-text-fill-color: var(--pk-green) !important;
  }
  [class*="Btn__btn_outline"] { border-color: var(--pk-green-deep) !important; }

  /* Legacy green-outline button (.button_border — the "Поддержать" support/donate
     CTA on profiles and posts). Pikabu ships it as an always-green outline button
     (border: var(--color-primary-700); color: var(--color-primary-900)), but our
     universal `* { border-color }` reset flattened its green ring to grey, erasing
     the affordance and leaving a borderless-looking button. Restore the green ring
     and lift the label to the dark-tuned brand green for readability. */
  .button.button_border,
  button.button_border,
  a.button_border {
    border-color: var(--pk-green-deep) !important;
    color: var(--pk-green) !important;
  }

  /* Mobile "download the app" button (`.header__app-link`, the green "Добавить" CTA
     in the drawer header). Pikabu gives it a brand-green outline AND a brand-green
     label; our universal `* { border-color }` reset flattened the ring, and the
     `.header a` label rule flattened the text. Only the ring had been restored, so the
     button shipped as a green outline wrapped around a grey label — and around a grey
     Apple glyph too, since that SVG paints from `currentColor`. Restore both. */
  a.header__app-link,
  .header__app-link,
  .header a.header__app-link,
  .header a.header__app-link span {
    border-color: var(--pk-green-deep) !important;
    color: var(--pk-green) !important;
  }

  /* "Post boost active" badge (rocket pill beside a boosted post's title). It carries its
     identity in three COMPONENT-LOCAL properties declared on the element itself, whose
     light defaults are a near-white #f9fff5 pill with a pale-green ring and label — a
     :root flip cannot reach them, and a colour-only border override left the pill white.
     Drive all three from Pikabu's own dark-theme values, which never apply here. */
  .story-boost-badge {
    --story-boost-badge-bg: #26331c !important;
    --story-boost-badge-stroke: #598039 !important;
    --story-boost-badge-content: #8fd35c !important;
    background-color: var(--story-boost-badge-bg) !important;
    border-color: var(--story-boost-badge-stroke) !important;
    color: var(--story-boost-badge-content) !important;
  }

  /* Full-page loading skeleton on the mobile layout. Its shimmer gradient reads two
     component-local properties that stay near-white (#f7f8fc / #ebedf2), so every route
     change flashed a screenful of bright bars. */
  .loader-skeleton {
    --skeleton-mainGradA: #333b45 !important;
    --skeleton-mainGradB: #262c34 !important;
  }

  /* ===== Sidebar widgets / community blocks ===== */
  .sidebar-block,
  .sidebar-game,
  .community-card,
  .community,
  .b-community,
  .widget,
  .block { background-color: var(--pk-surface) !important; }
  .sidebar-block__title,
  .widget__title,
  .community-card__title { color: var(--pk-text) !important; }

  /* Some sidebar / topic widgets hardcode a dark-grey #292a2e text and a white
     surface as literal values (not tokens), so they survive the :root flip and
     end up dark-on-dark. Restore readable text + dark surfaces explicitly. */
  .sidebar-game__title-text,
  .sidebar-game__name,
  .page-topic-links__name,
  .page-topic-links__title { color: var(--pk-text) !important; }
  .sidebar-game__title-subtext,
  .sidebar-game__genres { color: var(--pk-text-muted) !important; }

  /* The in-feed "Pikabu Игры" carousel variant hardcodes the same near-black
     #292a2e on the widget title + each game name — invisible on the dark card.
     Lift the title/name to readable light text; keep the genre subtitle muted. */
  .feed-games-carousel__title-text,
  .feed-games-carousel__name { color: var(--pk-text) !important; }
  .feed-games-carousel__genres,
  .feed-games-carousel__subtext { color: var(--pk-text-muted) !important; }
  .page-topic-links,
  .page-topic-links__link {
    background-color: var(--pk-surface) !important;
    color: var(--pk-text-soft) !important;
  }
  .page-topic-links__link:hover { background-color: var(--pk-surface-2) !important; color: var(--pk-text) !important; }

  .gamification-btn { background-color: var(--pk-surface-2) !important; }

  /* Profile "Цель дня" (goal of the day) gamification badge. `.daily-goal-badge`
     hardcodes a literal near-white #fbfff7 fill under a green accent label, so it
     shipped as a glaring light pill on the dark profile card. Pikabu darkens it to a
     dark olive #3a4d2a in its OWN dark theme (scoped to :root[data-theme-dark], which
     never applies here) — reuse that dark-green fill so the green "goal" identity reads. */
  .daily-goal-badge { background-color: #3a4d2a !important; }

  /* Profile "Станьте первым донатером автора" CTA. `.become-donator-btn` hardcodes a
     pale cream #f8fff2 fill under a green label — a glaring light pill on the dark
     profile card (Pikabu only darkens it in its own dark theme). Give it a dark-green
     donate surface with a brand-green label + ring so the "support the author" identity
     survives on dark. */
  .become-donator-btn {
    background-color: #1b2714 !important;
    color: var(--pk-green) !important;
    border-color: var(--pk-green-deep) !important;
  }

  /* Purchasable nickname badges. Each variant carries its own identity in
     --badge-shop-{bg,stroke,content}; a flat neutral surface plus the old `.hint`
     muting collapsed all six to the same grey pill. Drive the badge from its own
     tokens and pin each variant to a dark tint with a label above the WCAG floor.
     `!important` on the custom property is required: Pikabu re-declares these under
     :root[data-theme-dark], which outranks a plain override. */
  .pkb-badge-shop {
    /* The BASE token values are Pikabu's light default (#f2f3f7 pill / #5e6066 label),
       and they are what any badge WITHOUT a colour variant resolves to — e.g. the
       neutral `_gray` badge ("неисправен"), which Pikabu never gives a rule of its
       own. Those badges shipped as a white pill on the dark card. Give the base a dark
       default; the six colour variants below are later in this sheet at equal
       specificity, so they still win for the badges that own an identity colour. */
    --badge-shop-bg: #262c34 !important;
    --badge-shop-stroke: #39414b !important;
    --badge-shop-content: #c4cdd6 !important;
    background-color: var(--badge-shop-bg) !important;
    border-color: var(--badge-shop-stroke) !important;
    color: var(--badge-shop-content) !important;
    -webkit-text-fill-color: var(--badge-shop-content) !important;
  }
  .pkb-badge-shop_myata {
    --badge-shop-bg: #11261f !important;
    --badge-shop-stroke: #1d4034 !important;
    --badge-shop-content: #5cb98a !important;
  }
  .pkb-badge-shop_bubblegum {
    --badge-shop-bg: #330d1d !important;
    --badge-shop-stroke: #4d142c !important;
    --badge-shop-content: #e5679c !important;
  }
  .pkb-badge-shop_papaya {
    --badge-shop-bg: #2e1707 !important;
    --badge-shop-stroke: #47240b !important;
    --badge-shop-content: #e58d4e !important;
  }
  .pkb-badge-shop_banana {
    --badge-shop-bg: #1f1d17 !important;
    --badge-shop-stroke: #332f23 !important;
    --badge-shop-content: #e8ba23 !important;
  }
  .pkb-badge-shop_berry {
    --badge-shop-bg: #121633 !important;
    --badge-shop-stroke: #1e254d !important;
    --badge-shop-content: #8b96e8 !important;
  }
  .pkb-badge-shop_sliva {
    --badge-shop-bg: #231233 !important;
    --badge-shop-stroke: #371d4d !important;
    --badge-shop-content: #b98be0 !important;
  }

  /* The "donated" reaction pill keeps a cream #fff3eb fill (Pikabu only darkens it in
     its own dark theme, so a light-OS user gets a glaring island among dark pills). */
  button.emotion-btn_donated,
  .emotion-btn_donated {
    background-color: #2a2318 !important;
    color: #e0975a !important;
    -webkit-text-fill-color: #e0975a !important;
  }
  button.emotion-btn_donated:hover,
  .emotion-btn_donated:hover { background-color: #352c1e !important; }

  /* ===== Generic light surfaces caught by literal colours ===== */
  [style*="background: #fff"],
  [style*="background-color: #fff"],
  [style*="background:#fff"],
  [style*="background-color:#fff"] { background-color: var(--pk-surface) !important; }

  /* ===== Footer ===== */
  .footer,
  .page-footer,
  .b-footer {
    background-color: var(--pk-header) !important;
    color: var(--pk-text-muted) !important;
  }
  /* Scoped to the footer BLOCK itself. A `[class*="footer"] a` form also matches every
     `…__footer` sub-block on the site — the games-carousel card footer (whose filled
     brand-green "Играть" CTA it flattened to #c4cdd6, ~1.1:1 on the green) and the mobile
     drawer's `footer__email` newsletter (whose green consent links it greyed out). */
  .footer a,
  .footer a span,
  .page-footer a,
  .b-footer a,
  [class*="footer__link"],
  [class*="footer-link"] { color: var(--pk-text-soft) !important; }
  /* The footer's own app-download CTA is a filled green button, so it must keep the dark
     label every other filled green button on this theme carries. */
  .footer a.pkb-normal-btn,
  .footer a.button_success,
  .page-footer a.pkb-normal-btn {
    color: var(--pk-bg) !important;
    -webkit-text-fill-color: var(--pk-bg) !important;
  }

  /* ===== Code / quotes inside posts ===== */
  pre, code, .b-story-block__code {
    background-color: var(--pk-surface-2) !important;
    color: #a5d6ff !important;
    border-color: var(--pk-border) !important;
  }
  blockquote, .b-quote, .comment__quote {
    background-color: var(--pk-surface-2) !important;
    border-color: var(--pk-border) !important;
    color: var(--pk-text-soft) !important;
  }

  /* ===== Generic muted / hint text =====
     `.hint` is NOT a muted-text class on Pikabu — it marks "this element owns a
     tooltip", and it lands on shop badges, reaction pills and the logo. Muting it
     erased their colours; list the genuinely-muted elements instead. */
  .text-muted, .date, time, .comment__time, .story__date, .story__views {
    color: var(--pk-text-muted) !important;
  }

  /* Several metadata bits (comment counts, result counts, slider captions) use a
     literal mid-grey (#757880 / #45474d) rather than a token, which lands below
     the WCAG floor on dark. Lift them to the readable muted tone. */
  .story__comments-link-count,
  [class*="comments-link-count"],
  [class*="results-stories__count"],
  [class*="results-search__count"],
  [class*="Slider__info"] { color: var(--pk-text-muted) !important; }

  /* The legally-required advertising disclosure ("Реклама: <advertiser> ИНН …")
     on sponsored posts hardcodes a #6a6f76 grey that was fine on the original
     white card but drops to ~3:1 on the dark surface. Lift it to the readable
     muted tone (still low-emphasis, but above the WCAG floor). */
  .story__advert-info-text,
  [class*="advert-info-text"] { color: var(--pk-text-muted) !important; }

  /* Video / embedded-player poster placeholders show a light loading panel
     before the media paints — darken it so it matches the surrounding card. */
  [class*="player-block__preview"],
  [class*="video-file-player__player"],
  [class*="player-block__poster"] { background-color: #0d1117 !important; }

  /* --color-bright-900 (#ffffff) is Pikabu's ALWAYS-white foreground: it paints the
     label/icon of every brand fill, and it stays #ffffff even in Pikabu's own dark
     theme. We remap it to a dark tone at :root so labels read on this theme's
     lightened brand-green fills — but the same token also paints the chrome that
     floats over photos, video scrims and the black image viewer, where a dark tone is
     invisible. Restore the white foreground for those subtrees only. --color-black-440
     rides along: it colours the viewer's help/zoom icons on the same black backdrop. */
  .image-viewer,
  .external-video-viewer,
  .story__adult-overlay,
  .story_overlayed,
  .toast,
  .pls-not-block,
  .image-thumb__information,
  .image-thumb__duration,
  .story-fragment__play,
  .comment-external-video__play,
  .comment-external-video__state,
  .carousel_images .carousel__cur-slide,
  .dnd-overlay__content,
  [class*="player-block__state"] {
    --color-bright-900: #e9e9e9;
    --color-black-440: #e9e9e9;
  }

  /* INVERTED TOKENS USED AS SURFACES.
     --color-black-700/-800/-900/-940 are Pikabu's DARK greys; the palette flip above
     lifts them to light tones because they are text colours nearly everywhere. In a
     handful of places Pikabu instead uses them as a `background-color` — those
     surfaces flip the wrong way and come out near-white on the dark canvas. A DOM
     scan never catches them: every one is a transient, hover-only or state-only
     surface that is not in the tree at load time. Pin each back to a dark fill.
       .image-viewer-loader__stage   the lightbox spinner (a white disc on the black
                                     scrim while a full-size image loads; #444850 natively)
       .popup_warning .popup__container  a natively near-black (#212121) warning modal
       .comment-external-video__state:hover  hover fill on an embedded video's state chip
       .evaluation-emoji__title_framed / .avatar__note_banned / .icon--ui__close_story-preview
       video.player                  the legacy Vue player's letterbox area */
  .image-viewer-loader__stage,
  .evaluation-emoji__title_framed { background-color: #3a4149 !important; }
  .avatar__note_banned,
  .icon--ui__close_story-preview { background-color: var(--pk-border) !important; }
  video.player,
  .comment-external-video__state:hover { background-color: var(--pk-header) !important; }
  /* The warning modal paints its own text from --color-bright-900, which we remap to a
     dark tone — so darkening the container alone would leave it dark-on-dark. Restore
     the light foreground inside it, exactly as for the image viewer above. */
  .popup_warning .popup__container {
    background-color: var(--pk-surface) !important;
    --color-bright-900: #e9e9e9;
  }

  /* Every balloon popup (the story "..." overflow menu, share menu, community picker)
     lands on --pk-surface — the SAME fill as the story card it opens over — and Pikabu
     separates the two with `box-shadow: 0 4px 20px rgba(0,0,0,.08)`, a halo that only
     exists against a light page. On dark the panel has no edge at all: the menu items
     read as loose text floating on the post. Give the panel a real rim.
     `popup_modal` is excluded on purpose: on the auth/registration modal the container
     is a TRANSPARENT wrapper around a detached notice pill plus the card below it, so a
     rim there would trace a rectangle through empty space between the two. */
  .popup:not(.popup_modal) .popup__container {
    border: 1px solid var(--pk-border) !important;
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.6) !important;
  }

  /* Header ad-slot containers default to a literal white background; before an ad
     paints (or when none loads) that flashes a bright strip across the top of
     every page. Darken the empty container — loaded ad creatives paint over it. */
  .ads-placeholder,
  .external_branding,
  [class*="ads-placeholder"] { background-color: var(--pk-bg) !important; }

  /* Mobile offer banner. `.promo-banner` is a native Pikabu shell (it wraps an adfox
     offer + a green CTA) whose own CSS paints a pale-green #edffde background — a
     glaring light band across the top of the mobile layout. Darken only the shell;
     its green button and ad imagery sit on top, unaffected. Scope to `.promo-banner`
     exactly — NOT `.promo-banner-sticky`, which is the full-height app wrapper. */
  .promo-banner { background-color: var(--pk-surface) !important; }

  /* Highlight marker (author "highlighter" runs + search-term highlights). Its
     original light-yellow background is driven by tokens that the palette flip
     turns into a murky dark olive, while the text stayed near-black — leaving the
     whole highlighted run dark-on-dark and unreadable. Pin a deterministic muted
     dark-gold highlight with light text so the emphasis stays legible on dark. */
  .pkb-marker,
  mark,
  [class*="pkb-marker"] {
    background-color: #4a4327 !important;
    color: var(--pk-text) !important;
    -webkit-text-fill-color: var(--pk-text) !important;
  }

  /* Block-level highlight callout (author/promo CTA, e.g. "Пройди все испытания
     на Пикабу Игры"). Pikabu paints it from `background: var(--color-primary-200)`
     — the pale-green end of the brand ramp, which the palette flip leaves untouched,
     so it ships as a glaring pale-green island on the dark card while its text
     (--color-black-800, lifted light) turns near-invisible on it. Give it a dark-green
     surface with brand-green text so the green-callout identity survives on dark. */
  .pkb-highlight-block {
    background-color: #1b2714 !important;
    color: var(--pk-green) !important;
    border-color: var(--pk-green-deep) !important;
  }
  .pkb-highlight-block a { color: var(--pk-green) !important; }

  /* ===== Remaining literal light fills =====
     Every rule below paints a near-white / pale surface with a LITERAL colour, so the
     :root palette flip cannot reach it. Pikabu darkens most of them only under
     :root[data-theme-dark], which never applies to this theme. */

  /* Fundraising "support" icon button on a post, and the profile "goal of the day" card
     (the sibling of .daily-goal-badge above, which was fixed while this one was not). */
  /* The ring is restated because the blanket border reset flattens it — the button is a
     24px circle whose green outline plus green heart ARE the whole "support" affordance. */
  .pkb-donation-btn {
    background-color: #1d2615 !important;
    border-color: var(--pk-green-deep) !important;
  }
  .pkb-donation-btn:hover {
    background-color: #26331c !important;
    border-color: var(--pk-green) !important;
  }
  .gamification-daily-goal { background-color: #3a4d2a !important; }
  /* mobile header gamification pill */
  .mini-gamification-profile { background-color: #261306 !important; }

  /* "Промо" label on a sponsored post: pale-lilac pill + a dark purple label. Keep the
     purple identity, inverted for dark. */
  .story__promo .story-label {
    background-color: #2a1c33 !important;
    color: #b98be0 !important;
  }

  /* Placeholder card shown in place of a removed / unavailable post. */
  .story__gag_relative { background-color: var(--pk-surface) !important; }

  /* Author "info / warning / note" callout blocks inside a long-form post. Cream fill
     plus `color: #212121 !important` (#454648 on the mobile layout), so darkening the
     fill alone would leave the text unreadable. The mobile sheet nests the same block
     one level deeper, hence the second selector — it must match the site's own
     specificity to win the !important tie. */
  .aflm .story-block_type_text div[data-content],
  .aflm .story__content-inner .story-block_type_text div[data-content] {
    background-color: var(--pk-surface-2) !important;
    color: var(--pk-text-soft) !important;
  }
  .aflm .story-block_type_text div[data-content] h1,
  .aflm .story-block_type_text div[data-content] h2,
  .aflm .story-block_type_text div[data-content] h3,
  .aflm .story__content-inner .story-block_type_text div[data-content] h1,
  .aflm .story__content-inner .story-block_type_text div[data-content] h2,
  .aflm .story__content-inner .story-block_type_text div[data-content] h3 {
    color: var(--pk-text) !important;
  }

  /* Power-rating (super +/−) picker buttons: hover/press flash a light grey. */
  .power-rating-modal__btn:hover,
  .power-rating-modal__btn:active { background-color: var(--pk-border) !important; }

  /* Chip lists in the search filters (tag / author / community pickers) and the sidebar
     block dismiss control: the small action inside each chip turns pure white on hover. */
  .items-list__item a:hover,
  .company-blog-search-panel__item a:hover,
  .stories-search-item a:hover,
  .items-list__close:hover { background-color: var(--pk-border) !important; }
  .items-list__more:hover { background-color: var(--pk-surface) !important; }

  /* The "..." story menu keeps a pure-white fill on the item that opened it. */
  .context-menu__item.story__dots_active { background-color: var(--pk-border) !important; }

  /* Counter pill in the vertical menus (profile tabs) — a light-grey slab among dark
     chrome. The `_current` variant keeps its brand-green fill. */
  .menu__counter {
    background-color: var(--pk-border) !important;
    color: var(--pk-text) !important;
  }

  /* Floating "jump to comments" pill pinned to the bottom of a mobile post: a white
     capsule carrying a --color-black-700 label, which this theme lifts light — so the
     label vanishes on it. */
  .ex-scroller__body { background-color: var(--pk-surface) !important; }

  /* Logo/promo <img> holders that keep a white plate behind a transparent PNG. Darken
     the CONTAINER only; the artwork is untouched. */
  .sidebar__community-info img,
  .profile__promocode img { background-color: var(--pk-surface-2) !important; }

  /* Both green-tinted tiles above take their ring from a token, and the universal
     `* { border-color }` reset outranks a :root remap — so the tint would land while the
     ring stayed grey. Restate the ring from the same token. */
  .emotions-modal__btn_new { border-color: var(--reaction-popover-newStroke) !important; }
  .story__btn-promote { border-color: var(--story-btn-promote-stroke) !important; }
  .emotions-modal__alert { border-color: var(--c-alert-accentStroke) !important; }

  /* ===== Rings that ENCODE STATE, flattened by the universal border reset =====
     `* { border-color }` above is !important at specificity (0,0,0): it loses to any
     class/attribute selector but beats every token remap. Pikabu writes `!important`
     on exactly two ring rules — the LEGACY `.input:focus` and `.input_error` — so the
     legacy login/registration forms keep their green focus and red error rings unaided,
     and every modern ui-kit control needs its ring restated here.

     Focus / open ring on the ui-kit fields: the header search field, the search-filter
     tag/author/community comboboxes, the sort Select and the date-range inputs. Without
     it a focused field is pixel-identical to an idle one. */
  [class*="Input__host"]:focus-within,
  [class*="Textarea__host"]:focus-within,
  [class*="ComboBox__host_focused"],
  [class*="Select__host_open"] { border-color: var(--pk-green-deep) !important; }

  /* Invalid field: this ring is the ONLY error signal the component draws, so flattening
     it leaves a rejected form with no visible reason. */
  [class*="Input__host_error"],
  [class*="Textarea__host_error"],
  [class*="ComboBox__host_error"] { border-color: #e5594c !important; }

  /* Destructive button — see the --c-btn-negativeOutline-* remap above. */
  .pkb-normal-btn_negative-outline { border-color: var(--c-btn-negativeOutline-textStrokeDefault) !important; }
  .pkb-normal-btn_negative-outline:hover { border-color: var(--c-btn-negativeOutline-textStrokeHover) !important; }
  .pkb-normal-btn_negative-outline:active { border-color: var(--c-btn-negativeOutline-textStrokeClick) !important; }

  /* "Current theme" swatch in Pikabu's own theme picker. The ring is the swatch's ONLY
     selected marker (the tick inside it is opacity-driven), so a grey ring leaves the
     row with no indication of which theme is active. */
  .theme-picker__button_current { border-color: var(--pk-green) !important; }

  /* Green-variant tooltip card: the ring is what makes it read as the "positive" variant
     rather than the neutral one. */
  [class*="pkb-tooltip-base__host_green"] [class*="pkb-tooltip-base__card"] { border-color: var(--pk-green-deep) !important; }

  /* "Пикабу в цифрах" stat cards on /about. Pikabu paints each card a literal #fff and
     its number + caption a literal #212121. Our generic `.block` surface rule darkens
     the card but cannot reach the two literal text colours, so all five cards render
     blank — a lost fix half, not an unthemed surface, which is why a light-surface scan
     stays green while nothing is readable. */
  .content__numbers .block h3 { color: var(--pk-text) !important; }
  .content__numbers .block p { color: var(--pk-text-soft) !important; }

  /* Support-request widget on /information/help-request (a Usedesk form mounted straight
     into the page, not an iframe). Its panel, bot bubble, <select>, <textarea> and footer
     are literal light surfaces carrying near-black text, so the form shipped as a white
     card with two dark inputs punched into it.
     Every selector here MUST carry the #usedesk-widget prefix: the widget scopes its own
     rules to that mount id, so a plain `.uw__field-textarea` — or even
     `textarea.uw__field-textarea` — loses the !important tie on specificity and paints
     nothing. Key off the `uw__` classes rather than the `sc-dhKdcB` hashes beside them;
     those are styled-components names and rotate on every build. The green header,
     avatar and submit button are the widget's brand and stay. */
  #usedesk-widget .uw__widget-layout__content { background-color: var(--pk-bg) !important; }
  #usedesk-widget .uw__chat-message-content { background-color: var(--pk-surface) !important; }
  #usedesk-widget .uw__chat-message-content,
  #usedesk-widget .uw__chat-message__text { color: var(--pk-text-soft) !important; }
  #usedesk-widget .uw__chat-message__date { color: var(--pk-text-muted) !important; }
  #usedesk-widget .uw__field-text,
  #usedesk-widget .uw__field__select,
  #usedesk-widget .uw__field-textarea {
    background-color: var(--pk-surface-2) !important;
    color: var(--pk-text) !important;
    border-color: var(--pk-border) !important;
  }
  #usedesk-widget .uw__field-text::placeholder,
  #usedesk-widget .uw__field-textarea::placeholder { color: var(--pk-text-muted) !important; }
  #usedesk-widget .uw__footer {
    background-color: var(--pk-surface-2) !important;
    color: var(--pk-text-muted) !important;
  }
  /* The attach-file paperclip is a remote black-linework SVG loaded as a background-image,
     so darkening the panel under it erases it. Invert it; the header's close glyph is a
     white inline data-URI on the green bar and must NOT be touched, hence the scope. */
  #usedesk-widget .uw__file-loader .uw__icon { filter: invert(1) brightness(0.85) !important; }

  /* Labels sitting on the dark-tuned semantic tints above: Pikabu's saturated mid-tones
     fall under the WCAG floor on them, so lift the red and blue ones. (The green and
     amber labels already clear it.) */
  .pkb-badge_highlight { color: var(--pk-green) !important; }
  .pkb-profile-rating-counter_red { color: #ef6a5d !important; }
  .company-blog-badge { color: #45b6dd !important; }
}
